-- Reference PostgreSQL schema. Production deployments should apply this through Alembic.
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(190) UNIQUE NOT NULL, password_hash VARCHAR(500) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS water_bodies (id SERIAL PRIMARY KEY, slug VARCHAR(100) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, city VARCHAR(120) NOT NULL, country VARCHAR(80) NOT NULL DEFAULT 'India', latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'RESEARCH RECORD', description TEXT NOT NULL DEFAULT '', source_period VARCHAR(100) NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS observations (id SERIAL PRIMARY KEY, water_body_id INTEGER NOT NULL REFERENCES water_bodies(id) ON DELETE CASCADE, user_id INTEGER REFERENCES users(id) ON DELETE SET NULL, observed_at TIMESTAMPTZ NOT NULL, source VARCHAR(80) NOT NULL, source_record_id VARCHAR(160), note TEXT NOT NULL DEFAULT '', site_code VARCHAR(32) NOT NULL, lat DOUBLE PRECISION NOT NULL, lon DOUBLE PRECISION NOT NULL, temperature_c DOUBLE PRECISION, ph DOUBLE PRECISION, tds_mg_l DOUBLE PRECISION, do_mg_l DOUBLE PRECISION, bod_mg_l DOUBLE PRECISION, cod_mg_l DOUBLE PRECISION, nitrate_mg_l DOUBLE PRECISION, phosphate_mg_l DOUBLE PRECISION, conductivity_us_cm DOUBLE PRECISION, biodiversity_signal DOUBLE PRECISION NOT NULL DEFAULT 0, human_signal DOUBLE PRECISION NOT NULL DEFAULT 0, image_signal DOUBLE PRECISION NOT NULL DEFAULT 0, quality_score DOUBLE PRECISION NOT NULL DEFAULT 1, provenance JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX IF NOT EXISTS ix_observations_water_body_time ON observations(water_body_id, observed_at);
CREATE TABLE IF NOT EXISTS bookmarks (id SERIAL PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, water_body_id INTEGER NOT NULL REFERENCES water_bodies(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT uq_user_water_body_bookmark UNIQUE(user_id, water_body_id));
CREATE TABLE IF NOT EXISTS incidents (id SERIAL PRIMARY KEY, water_body_id INTEGER NOT NULL REFERENCES water_bodies(id) ON DELETE CASCADE, code VARCHAR(32) UNIQUE NOT NULL, detected_at TIMESTAMPTZ NOT NULL, severity VARCHAR(24) NOT NULL, confidence DOUBLE PRECISION NOT NULL, title VARCHAR(180) NOT NULL, summary TEXT NOT NULL, evidence_count INTEGER NOT NULL DEFAULT 0, evidence JSONB NOT NULL DEFAULT '{}'::jsonb);
